export async function send(job: Job, policy: RetryPolicy) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await deliver(job);
    } catch (error) {
      if (attempt >= policy.maxAttempts) throw error;
      await sleep(policy.backoff(attempt));
    }
  }
}

