// Server-built, per round, from `git diff -M -U0 base head` plus a -U3 pass for what Bitbucket shows.
type LineIndex = {
    files: { path: string; from?: string; added: Range[]; removed: Range[]; shown: Range[];
             housekeeping?: 'lock' | 'generated' | 'binary' | 'whitespace' }[];
    repeats: { key: string; hunks: HunkRef[]; identical: boolean[] }[];   // normalised text match
    moves: { from: HunkRef; to: HunkRef }[];                             // removed block == added block, 3+ lines
};

// Agent -> page. Refused until every added and removed line is in some piece.
{ type: 'read.outline', pages: { id, kind: 'concept' | 'repeat' | 'tests' | 'housekeeping', title, order,
    pieces: { id, file, lines: '40-72', oldLines?: '38-66', view?: 'now' | 'diff', move?: true }[] }[] }
{ type: 'read.page.upsert', page: id, blocks: BlockEntry[], pieces: { id, note?, related?: CodeRef[] }[],
    tests?: { piece, title, pseudo }[] }
{ type: 'read.page.add', page: id, thread: string, blocks: BlockEntry[] }   // marked 'asked', unticks what it changes

// Page -> server (not sent to the agent)
{ type: 'read.tick', piece: id, read: boolean, how: 'manual' | 'auto' }

// Changed
noteContent.anchor  // gains end (drag selection) and repeat?: { page, onlyHere: boolean }
reviewers.start     // gains technique: 'deck' | 'readthrough' | 'both'; strength gains 'none'
reviewPreferences   // gains technique, readthrough: { view: 'auto'|'now'|'diff', tests: 'title'|'pseudo'|'code', autoTick }
